using Microsoft.AspNetCore.SignalR; using Microsoft.EntityFrameworkCore; using QualifyAI.Application; using QualifyAI.Domain; using QualifyAI.Infrastructure;
namespace QualifyAI.Api;
public static class PublicChatEndpoints { public record ChatRequest(string Tenant,string? ConversationId,string? Email,string Message); public static void MapPublicChat(this IEndpointRouteBuilder app){ app.MapPost("/api/public/chat",async(ChatRequest r,AppDbContext db,LeadQualificationService qualifier,IKnowledgeRetriever knowledge,IAiProvider ai,IHubContext<ConversationHub> hub)=>{ var tenant=await db.Tenants.FirstOrDefaultAsync(x=>x.Slug==r.Tenant&&x.IsActive); if(tenant is null)return Results.NotFound(new{error="tenant_not_found"}); Conversation? conv=null; if(Guid.TryParse(r.ConversationId,out var cid))conv=await db.Conversations.FirstOrDefaultAsync(x=>x.Id==cid&&x.TenantId==tenant.Id); if(conv is null){ Contact? c=null; if(!string.IsNullOrWhiteSpace(r.Email))c=await db.Contacts.FirstOrDefaultAsync(x=>x.TenantId==tenant.Id&&x.Email==r.Email); if(c is null){c=new Contact{TenantId=tenant.Id,Email=r.Email??"",LifecycleStage="lead"};db.Contacts.Add(c);} var q=qualifier.Score(r.Message); var lead=new Lead{TenantId=tenant.Id,ContactId=c.Id,Score=q.score,Temperature=q.temperature,IntentSummary=r.Message,Source="web"}; db.Leads.Add(lead); conv=new Conversation{TenantId=tenant.Id,ContactId=c.Id,LeadId=lead.Id}; db.Conversations.Add(conv); foreach(var reason in q.reasons) db.LeadScoreExplanations.Add(new LeadScoreExplanation{TenantId=tenant.Id,LeadId=lead.Id,Factor=reason.factor,Points=reason.points,Reason=reason.reason}); }
 var inbound=new Message{TenantId=tenant.Id,ConversationId=conv.Id,SenderType="visitor",Text=r.Message}; db.Messages.Add(inbound); var hits=await knowledge.SearchAsync(tenant.Id,r.Message,3); var context=string.Join("
",hits.Select(x=>$"[{x.Title}] {x.Text}")); var answer=await ai.CompleteAsync($"Use tenant knowledge. Context:
{context}",r.Message); var outbound=new Message{TenantId=tenant.Id,ConversationId=conv.Id,SenderType="ai",Text=answer}; db.Messages.Add(outbound); conv.LastMessageAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); await hub.Clients.Group($"conversation:{conv.Id}").SendAsync("message",new{outbound.Id,outbound.SenderType,outbound.Text,outbound.CreatedAtUtc}); return Results.Ok(new{conversationId=conv.Id,message=answer,sources=hits.Select(x=>new{x.DocumentId,x.Title,x.Score}),leadId=conv.LeadId}); }).AllowAnonymous(); } }
